<?php defined('BASEPATH') OR exit('No direct script access allowed'); $ro=!empty($read_only); $res=$reservation?:null; $price=$res?(float)$res->resPrice:(float)$room->rmPrice; $other=$res?(float)$res->resOtherCharges:0; $discountAmount=$res?(float)$res->resDiscountAmount:0; $total=$price-$discountAmount+$other; ?>
<div class="container-fluid" style="background:#fff;border:1px solid #ccc;border-radius:10px;padding:20px;max-width:900px">
<h2><?= $ro?'Reservation Details':'New Reservation' ?> — <?= html_escape($room->rmTitle) ?></h2>
<?php if($this->session->flashdata('error')): ?><div class="alert alert-danger"><?= html_escape($this->session->flashdata('error')) ?></div><?php endif; ?>
<form method="post" action="<?= site_url('pos/reservations/do_book/'.$room->rmID) ?>">
<input type="hidden" name="resDate" value="<?= html_escape($date) ?>">
<div class="form-group"><label>Date</label><input class="form-control" value="<?= html_escape($date) ?>" readonly></div>
<div class="form-group"><label>Guest name</label><input class="form-control" name="guest_name" value="<?= html_escape($res->resGuestName??'') ?>" <?= $ro?'readonly':'required' ?>></div>
<div class="form-group"><label>Room price</label><input class="form-control" value="<?= number_format($price,2,'.','') ?>" readonly></div>
<div class="form-group"><label>Room discount</label><?php if($ro): ?><input class="form-control" value="<?= $res && $res->resRoomDiscountID ? 'Discount applied (amount: '.number_format($discountAmount,2).')':'None' ?>" readonly><?php else: ?><select class="form-control" name="room_discount_id" id="discount"><option value="">No discount</option><?php foreach($discounts as $d): ?><option value="<?= (int)$d->disID ?>" data-percent="<?= (float)$d->disPercent ?>"><?= html_escape($d->disName) ?> (<?= (float)$d->disPercent ?>%)</option><?php endforeach; ?></select><?php endif; ?></div>
<div class="form-group"><label>Discount amount</label><input class="form-control" id="discount-amount" value="<?= number_format($discountAmount,2,'.','') ?>" readonly></div>
<div class="form-group"><label>Other charges</label><input class="form-control" type="number" min="0" step="0.01" name="other_charges" id="other" value="<?= number_format($other,2,'.','') ?>" <?= $ro?'readonly':'required' ?>></div>
<div class="form-group"><label>Total due at check-in</label><input class="form-control" id="total" value="<?= number_format($total,2,'.','') ?>" readonly></div>
<?php if($ro && $res): ?><div class="form-group"><label>Payment recorded at reservation</label><input class="form-control" value="<?= number_format((float)$res->resPayment,2) ?>" readonly></div><?php endif; ?>
<?php if(!$ro): ?><div class="alert alert-info">No payment is collected when creating a reservation. Payment is collected at guest check-in.</div><button class="btn btn-primary">Save Reservation</button><?php endif; ?>
<a class="btn btn-default" href="<?= site_url('pos/reservations?date='.rawurlencode($date)) ?>">Back</a></form></div>
<?php if(!$ro): ?><script>(function(){var price=<?= json_encode((float)$room->rmPrice) ?>;function calc(){var s=document.getElementById('discount'),pct=s&&s.selectedOptions[0]?parseFloat(s.selectedOptions[0].dataset.percent)||0:0;var d=Math.round(price*pct)/100;d=Math.round(d*100)/100;var o=Math.max(0,parseFloat(document.getElementById('other').value)||0);var t=Math.round((price-d+o)*100)/100;document.getElementById('discount-amount').value=d.toFixed(2);document.getElementById('total').value=t.toFixed(2);}['discount','other'].forEach(function(id){var e=document.getElementById(id);if(e){e.addEventListener('input',calc);e.addEventListener('change',calc);}});calc();})();</script><?php endif; ?>
